pous.declaration:
FUNCTION_BLOCK IPv4Parse
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT;
END_VAR
VAR
    i : INT;
    n : INT;
    segCount : INT;
    segVal : INT;
    result : UDINT;
    valid : BOOL;
    started : BOOL;
    ch : BYTE;
END_VAR

pous.implementation:
n := LEN(ipText);
segCount := 0;
segVal := 0;
result := 0;
valid := TRUE;
started := FALSE;
FOR i := 1 TO n DO
    ch := ipText[i];
    IF ch = 46 THEN
        IF NOT started OR segVal > 255 THEN
            valid := FALSE;
        END_IF
        result := SHL(result, 8) OR INT_TO_UDINT(segVal);
        segCount := segCount + 1;
        segVal := 0;
        started := FALSE;
    ELSIF ch >= 48 AND ch <= 57 THEN
        started := TRUE;
        segVal := segVal * 10 + (BYTE_TO_INT(ch) - 48);
        IF segVal > 255 THEN
            valid := FALSE;
        END_IF
    ELSE
        valid := FALSE;
    END_IF
END_FOR
IF NOT started OR segVal > 255 THEN
    valid := FALSE;
END_IF
result := SHL(result, 8) OR INT_TO_UDINT(segVal);
segCount := segCount + 1;
IF valid AND segCount = 4 THEN
    ipValue := result;
ELSE
    ipValue := 0;
END_IF
